def segments_by_k(grid, color):
 from collections import defaultdict
 pts=defaultdict(set)
 for r,row in enumerate(grid):
  for c,x in enumerate(row):
   if x==color: pts[c-r].add(r)
 segs=[]
 for k,rs in pts.items():
  sr=sorted(rs)
  groups=[]
  for r in sr:
   if not groups or r>groups[-1][-1]+1: groups.append([r])
   else: groups[-1].append(r)
  for g in groups:
   segs.append((k,min(g),max(g),2*min(g)+k,2*max(g)+k))
 return sorted(segs)

def fill_model(grid,color):
 n=len(grid); out=[row.copy() for row in grid]
 segs=segments_by_k(grid,color)
 # adjacent by k values, with all segment groups; require consecutive distinct k tracks sorted. Group same k segments perhaps adjacent lines same offsets irrelevant.
 byk={}
 for s in segs: byk.setdefault(s[0],[]).append(s)
 ks=sorted(byk)
 for k1,k2 in zip(ks,ks[1:]):
  for a in byk[k1]:
   for b in byk[k2]:
    lo=max(a[3],b[3]); hi=min(a[4],b[4])
    if lo>hi: continue
    for r in range(n):
     for c in range(n):
      u=r+c; v=c-r
      if lo<=u<=hi and k1<v<k2 and out[r][c]==8: out[r][c]=2
 return out

