def fill_sweep2(grid,color):
 n=len(grid); out=[row.copy() for row in grid]
 segs=segments_by_k(grid,color)
 for u in range(2*n-1):
  active=sorted(set(k for k,r0,r1,umin,umax in segs if umin<=u<=umax))
  for k1,k2 in zip(active,active[1:]):
   for v in range(k1+1,k2):
    if (u-v)%2: continue
    r=(u-v)//2;c=(u+v)//2
    if 0<=r<n and 0<=c<n and out[r][c]==8: out[r][c]=2
 return out
